import { RolesPage } from "@/components/openlmis/roles-page/roles-page"

// A Next.js App Router route; in any other React app, render RolesPage from your own route.
export default function Page() {
  return <RolesPage />
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  useTable,
} from "@tanstack/react-table"
import { PlusIcon, SearchXIcon, ShieldIcon } from "lucide-react"
import { useCallback, useMemo, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  DataTable,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  ListToolbar,
  ListToolbarEnd,
  ListToolbarFilter,
  ListToolbarSearch,
} from "@/components/blocks/openlmis/list-toolbar"
import type { RightType } from "@/components/blocks/openlmis/role-assignments-table/role-assignments"
import {
  RoleFormDialog,
  type RoleFormDialogTarget,
} from "@/components/blocks/openlmis/role-form-dialog/role-form-dialog"
import type { RoleFormResult } from "@/components/blocks/openlmis/role-form-dialog/role-form"
import { ROLE_TYPES } from "@/components/blocks/openlmis/role-form-dialog/role-form"
import { RoleRightsDialog } from "@/components/blocks/openlmis/role-rights-dialog"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"
import { PageBreadcrumbs } from "@/components/openlmis/page-breadcrumbs"
import { SearchInput } from "@/components/openlmis/search-input/search-input"
import { SelectFilter } from "@/components/openlmis/select-filter"

import { type ListedRole, MOCK_RIGHTS, MOCK_ROLES } from "@/components/openlmis/roles-page/mock-roles"
import { createRoleColumns, HIDEABLE_COLUMNS } from "@/components/openlmis/roles-page/role-columns"
import {
  filterRoles,
  type RoleSortField,
  type RolesQuery,
  sortRoles,
} from "@/components/openlmis/roles-page/roles-list"

const INITIAL_QUERY: RolesQuery = {
  search: "",
  type: "",
  sortBy: "name",
  sortDesc: false,
  pageIndex: 0,
  pageSize: 10,
}

const getRowId = (role: ListedRole) => role.id

type OpenDialog =
  | { kind: "role"; target: RoleFormDialogTarget }
  | { kind: "rights"; roleId: string }

type Notice = { title: string; description: string }

type RolesPageProps = {
  /** Whether the user may create and edit roles; without it the list is read only. */
  canEdit?: boolean
  /** Whether the user may see what each role grants. */
  canViewRights?: boolean
}

/** The roles list screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function RolesPage({
  canEdit = true,
  canViewRights = true,
}: RolesPageProps) {
  const [roles, setRoles] = useState(MOCK_ROLES)
  const [query, setQuery] = useState(INITIAL_QUERY)
  const [dialog, setDialog] = useState<OpenDialog>()
  const [notice, setNotice] = useState<Notice>()
  const closeDialog = () => setDialog(undefined)
  /** A filter or sort starts again from the first page; paging keeps the rest. */
  const update = (patch: Partial<RolesQuery>) => {
    setNotice(undefined)
    setQuery((previous) => ({
      ...previous,
      ...patch,
      pageIndex: "pageIndex" in patch ? (patch.pageIndex ?? 0) : 0,
    }))
  }

  // Stable, so the columns built from them keep their identity between renders.
  const onEdit = useCallback((roleId: string) => {
    setNotice(undefined)
    setDialog({ kind: "role", target: roleId })
  }, [])
  const onViewRights = useCallback((roleId: string) => {
    setNotice(undefined)
    setDialog({ kind: "rights", roleId })
  }, [])
  const columns = useMemo(
    () =>
      createRoleColumns({
        onEdit: canEdit ? onEdit : undefined,
        onViewRights: canViewRights ? onViewRights : undefined,
      }),
    [canEdit, canViewRights, onEdit, onViewRights]
  )
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  // Every role is in memory, so filtering, sorting and paging happen here.
  const matching = useMemo(
    () => sortRoles(filterRoles(roles, query), query.sortBy, query.sortDesc),
    [roles, query]
  )
  // A filter that leaves fewer pages is held to the last page that exists.
  const lastPage = Math.max(0, Math.ceil(matching.length / query.pageSize) - 1)
  const pagination = useMemo(
    () => ({
      pageIndex: Math.min(query.pageIndex, lastPage),
      pageSize: query.pageSize,
    }),
    [query.pageIndex, query.pageSize, lastPage]
  )
  const data = useMemo(
    () =>
      matching.slice(
        pagination.pageIndex * pagination.pageSize,
        (pagination.pageIndex + 1) * pagination.pageSize
      ),
    [matching, pagination]
  )
  // Memoized: the table compares controlled state by reference and would reset it every render.
  const sorting = useMemo(
    () => [{ id: query.sortBy, desc: query.sortDesc }],
    [query.sortBy, query.sortDesc]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data,
    getRowId,
    rowCount: matching.length,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: { pagination, sorting, columnVisibility: columnView.visibility },
    onPaginationChange: (updater) =>
      update(functionalUpdate(updater, pagination)),
    onSortingChange: (updater) => {
      const [next] = functionalUpdate(updater, sorting)
      if (next)
        update({ sortBy: next.id as RoleSortField, sortDesc: next.desc })
    },
  })

  const roleTarget = dialog?.kind === "role" ? dialog.target : undefined
  const editing = roles.find((role) => role.id === roleTarget)
  const rightsRole =
    dialog?.kind === "rights"
      ? roles.find((role) => role.id === dialog.roleId)
      : undefined
  const isFiltered = Boolean(query.search || query.type)

  const saveRole = (
    result: RoleFormResult,
    existing: ListedRole | undefined
  ) => {
    if (existing) {
      setRoles((current) =>
        current.map((role) =>
          role.id === existing.id ? { ...role, ...result } : role
        )
      )
      setNotice({
        title: "Role Updated",
        description:
          existing.count === 0
            ? `Changes to ${result.name} are saved.`
            : `Changes to ${result.name} are saved and apply to ${existing.count === 1 ? "1 user" : `${existing.count} users`}.`,
      })
    } else {
      setRoles((current) => [
        ...current,
        { id: `role-${current.length + 1}`, ...result, count: 0 },
      ])
      setNotice({
        title: "Role Created",
        description: `${result.name} is ready to give to users.`,
      })
    }
    closeDialog()
  }

  return (
    <Workspace>
      <PageBreadcrumbs
        items={[
          { label: "Home", href: "#" },
          { label: "Administration" },
          { label: "Roles" },
        ]}
      />
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <ShieldIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Roles</WorkspaceTitle>
          <WorkspaceDescription>
            Named sets of rights to give to users.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div className="flex flex-col gap-4" ref={measureContent}>
          {notice && (
            <Callout title={notice.title} tone="success">
              {notice.description}
            </Callout>
          )}
          <ListToolbar>
            <ListToolbarSearch>
              <SearchInput
                label="Search by name or description"
                onValueChange={(search) => update({ search })}
                value={query.search}
              />
            </ListToolbarSearch>
            <ListToolbarFilter>
              <SelectFilter
                label="Role Type"
                onValueChange={(type) =>
                  update({ type: type as RightType | "" })
                }
                options={ROLE_TYPES.map((item) => ({
                  value: item.type,
                  label: item.label,
                }))}
                value={query.type}
              />
            </ListToolbarFilter>
            <ListToolbarEnd>
              <ColumnViewOptions
                columns={HIDEABLE_COLUMNS}
                onReset={columnView.onReset}
                onVisibilityChange={columnView.onVisibilityChange}
                visibility={columnView.visibility}
              />
            </ListToolbarEnd>
            {canEdit && (
              <div className="w-full @2xl/main:w-auto">
                <Button
                  className="w-full"
                  onClick={() => {
                    setNotice(undefined)
                    setDialog({ kind: "role", target: "new" })
                  }}
                >
                  <PlusIcon data-icon="inline-start" />
                  Create Role
                </Button>
              </div>
            )}
          </ListToolbar>

          <DataTable
            empty={
              isFiltered ? (
                <DataTableEmpty
                  action={
                    <Button
                      onClick={() => update({ search: "", type: "" })}
                      variant="destructive"
                    >
                      Clear Filters
                    </Button>
                  }
                  description="No role matches these filters."
                  icon={<SearchXIcon />}
                  title="No Matching Roles"
                />
              ) : (
                <DataTableEmpty
                  description="Roles you create appear here."
                  icon={<ShieldIcon />}
                  title="No Roles Yet"
                />
              )
            }
            footer={
              matching.length > 0 && <DataTablePagination table={table} />
            }
            table={table}
          />
        </div>
      </WorkspaceContent>

      <RoleFormDialog
        canEdit={canEdit}
        holders={editing?.count ?? 0}
        onClose={closeDialog}
        onSubmit={(result) => saveRole(result, editing)}
        rights={MOCK_RIGHTS}
        role={editing}
        roles={roles}
        target={roleTarget}
      />
      <RoleRightsDialog onClose={closeDialog} role={rightsRole} />
    </Workspace>
  )
}

"use client"

import { createColumnHelper } from "@tanstack/react-table"
import { EllipsisIcon, ListChecksIcon, PencilIcon } from "lucide-react"
import { useCallback, useRef } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { roleTypeOf } from "@/components/blocks/openlmis/role-assignments-table/role-assignments"
import { roleTypeInfo } from "@/components/blocks/openlmis/role-form-dialog/role-form"

import type { ListedRole } from "@/components/openlmis/roles-page/mock-roles"

/** The columns the View menu lists, in order; the role's name is left out, so it always shows. */
export const HIDEABLE_COLUMNS: (ResponsiveColumn & { label: string })[] = [
  { id: "type", label: "Role Type", hideBelow: "md" },
  { id: "description", label: "Description", hideBelow: "4xl" },
  { id: "count", label: "Number Of Users", hideBelow: "xl" },
]

const columnHelper = createColumnHelper<DataTableFeatures, ListedRole>()

/** Each is left out when the user may not do it, and the menu goes when both are. */
export type RoleRowActions = {
  onEdit?: ((roleId: string) => void) | undefined
  onViewRights?: ((roleId: string) => void) | undefined
}

export function createRoleColumns(actions: RoleRowActions) {
  const hasActions = Boolean(actions.onEdit || actions.onViewRights)
  return columnHelper.columns([
    columnHelper.accessor("name", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Role" />
      ),
      cell: ({ getValue }) => <span className="font-medium">{getValue()}</span>,
      meta: { className: "@xl/table:w-1/3 @4xl/table:w-1/4" },
    }),
    columnHelper.accessor((role) => roleTypeOf(role), {
      id: "type",
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Role Type" />
      ),
      cell: ({ getValue }) => {
        const type = getValue()
        return type ? (
          roleTypeInfo(type).label
        ) : (
          <span className="text-muted-foreground">No Type</span>
        )
      },
      meta: { className: "@xl/table:w-40" },
    }),
    columnHelper.accessor("description", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Description" />
      ),
      cell: ({ getValue }) =>
        getValue() || <span className="text-muted-foreground">-</span>,
      enableSorting: false,
    }),
    columnHelper.accessor("count", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Number Of Users" />
      ),
      cell: ({ getValue }) => (
        <span className="tabular-nums">{getValue()}</span>
      ),
      meta: { className: "w-36" },
    }),
    ...(hasActions
      ? [
          columnHelper.display({
            id: "actions",
            header: () => <span className="sr-only">Actions</span>,
            cell: ({ row }) => (
              <RoleActions actions={actions} role={row.original} />
            ),
            meta: { className: "w-16" },
          }),
        ]
      : []),
  ])
}

/** Keeps a closing menu from taking focus back to its trigger when an item opened a dialog, which then owns focus. */
function useMenuOpensDialog() {
  const opened = useRef(false)

  const onOpenChange = useCallback((open: boolean) => {
    if (open) opened.current = false
  }, [])
  const finalFocus = useCallback(() => !opened.current, [])
  const opensDialog = useCallback(
    (open: () => void) => () => {
      opened.current = true
      open()
    },
    []
  )

  return { onOpenChange, finalFocus, opensDialog }
}

function RoleActions({
  role,
  actions: { onEdit, onViewRights },
}: {
  role: ListedRole
  actions: RoleRowActions
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions for ${role.name}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          {onEdit && (
            <DropdownMenuItem onClick={menu.opensDialog(() => onEdit(role.id))}>
              <PencilIcon />
              Edit
            </DropdownMenuItem>
          )}
          {onViewRights && (
            <DropdownMenuItem
              onClick={menu.opensDialog(() => onViewRights(role.id))}
            >
              <ListChecksIcon />
              View Rights
            </DropdownMenuItem>
          )}
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

import {
  type RightType,
  type Role,
  roleTypeOf,
} from "@/components/blocks/openlmis/role-assignments-table/role-assignments"
import { ROLE_TYPES } from "@/components/blocks/openlmis/role-form-dialog/role-form"

import type { ListedRole } from "@/components/openlmis/roles-page/mock-roles"

export const ROLE_SORT_FIELDS = ["name", "type", "count"] as const

export type RoleSortField = (typeof ROLE_SORT_FIELDS)[number]

export type RolesQuery = {
  search: string
  /** An empty string means every type. */
  type: RightType | ""
  sortBy: RoleSortField
  sortDesc: boolean
  pageIndex: number
  pageSize: number
}

// Folds case and accents, so "sante" finds "Santé".
const fold = (text: string) =>
  text.normalize("NFD").replace(/\p{M}/gu, "").toLowerCase()

export function filterRoles(
  roles: readonly ListedRole[],
  { search, type }: Pick<RolesQuery, "search" | "type">
) {
  const term = fold(search.trim())
  return roles.filter(
    (role) =>
      (!type || roleTypeOf(role) === type) &&
      (!term ||
        [role.name, role.description ?? ""].some((text) =>
          fold(text).includes(term)
        ))
  )
}

const byName = (a: Role, b: Role) =>
  a.name.localeCompare(b.name, undefined, { sensitivity: "base" })

// A role with no rights has no type, so it sorts after the four.
const typeRank = (role: Role) => {
  const index = ROLE_TYPES.findIndex((item) => item.type === roleTypeOf(role))
  return index === -1 ? ROLE_TYPES.length : index
}

const COMPARE: Record<RoleSortField, (a: ListedRole, b: ListedRole) => number> =
  {
    name: byName,
    type: (a, b) => typeRank(a) - typeRank(b),
    count: (a, b) => a.count - b.count,
  }

export function sortRoles(
  roles: readonly ListedRole[],
  field: RoleSortField,
  desc: boolean
) {
  const compare = COMPARE[field]
  // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh copy; toSorted needs the ES2023 lib
  return [...roles].sort(
    (a, b) => (desc ? -compare(a, b) : compare(a, b)) || byName(a, b)
  )
}
